from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class Links(SchemaObject):
    rel = SchemaField(name="rel")
    href = SchemaField(name="href", not_null=True)

    def __init__(self, rel, href):
        self.rel = rel
        self.href = href

        super(Links, self).__init__()


class CopyManagedObjectsResponseV1(SchemaObject):
    action_id = SchemaField(name="action_id", not_null=True)
    links = SchemaField(name='links', many=True, klass=Links, optional=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='error_message', optional=True)
    revision = SchemaField(name='revision', optional=True)

    def __init__(self, action_id, links, status, error_message, revision):
        self.action_id = action_id
        self.links = links
        self.status = status
        self.error_message = error_message
        self.revision = revision

        super(CopyManagedObjectsResponseV1, self).__init__()
